cat > /tmp/quantdiag.m <<'EOF'
% Recompute quantH2O for records c and d with correct (seconds) units
function val = h2o(met, ref, metTR, metTE, watTR, watTE, T1W, T2W, T1M, T2M, extra_scale)
  % TR/TE already in SECONDS
  T1F = (1-exp(-watTR/T1W)) / (1-exp(-metTR/T1M));
  T2F = exp(-watTE/T2W) / exp(-metTE/T2M);
  val = (met/ref) * 55500 * 0.65 * T1F * T2F * extra_scale;
end
% 7T: T1W=1.675 T2W=0.0525 ; Cr: T1M=1.76 T2M=0.107
T1W=1.675; T2W=0.0525; T1M=1.76; T2M=0.107;
% record c
c = h2o(1, 1, 1.37, 0.061, 2.41, 0.019, T1W, T2W, T1M, T2M, 1);
% record d
d = h2o(1.64945, 1, 4.2, 0.039, 2.6, 0.009, T1W, T2W, T1M, T2M, 1);
disp(['correct-seconds c = ' num2str(c,10)]);
disp(['correct-seconds d = ' num2str(d,10)]);
disp(['ratio c/d = ' num2str(c/d,10)]);
% Now with the BUG: extra *1e-3 applied inside (TR/TE in ms effectively)
cbug = h2o(1, 1, 1.37e-3, 0.061e-3, 2.41e-3, 0.019e-3, T1W, T2W, T1M, T2M, 1);
dbug = h2o(1.64945, 1, 4.2e-3, 0.039e-3, 2.6e-3, 0.009e-3, T1W, T2W, T1M, T2M, 1);
disp(['bug(ms) c = ' num2str(cbug,10)]);
disp(['bug(ms) d = ' num2str(dbug,10)]);
