function subspec(fname, tag)
  d = load(fname);
  fprintf('=== %s (%s) ===\n', tag, d.sequence);
  n = size(d.fids,3);
  names = d.subspectrum_names;
  for s = 1:n
    spec = squeeze(d.specs(:,1,s));
    fid  = squeeze(d.fids(:,1,s));
    % Cr peak near 3.027 ppm
    ppm = d.ppm(1,:);
    [~, imax] = max(abs(spec(ppm>2.9 & ppm<3.2)));
    crmax = max(abs(spec(ppm>2.9 & ppm<3.2)));
    crppm = ppm(ppm>2.9 & ppm<3.2)(imax);
    % overall max
    [gmax, gix] = max(abs(spec));
    fprintf('  subspec %d (%s): cr~%.4fppm amp=%.4f  overall_max=%.4f @%.3f  sum_abs_spec=%.4f\n', ...
        s, names{s}, crppm, crmax, gmax, ppm(gix), sum(abs(spec)));
  end
end
